  ('trello', 'Trello', 'dominio', ARRAY[]::text[], 4, 'Trello: tablero de tarjetas para organizar tareas y ver en qué estado está cada una', true),
  ('mailchimp', 'Mailchimp', 'dominio', ARRAY[]::text[], 8, 'Mailchimp: plataforma para armar y enviar campañas de email a una lista de contactos', true)
